/**
 * Canon type contract. content/canon/canon.json (generated by scripts/canon-merge.ts
 * from source.json + extended-*.json) must satisfy `Canon`.
 * Every number shown anywhere in MERIDIAN must be read from this data.
 *
 * Owners:
 *   source.json      -> canon extractor (facts from lore/source-facility-inventory.html only)
 *   extended-a.json  -> canon extender A (sites, reactors, org, roster, compartments, council, numbering)
 *   extended-b.json  -> canon extender B (glossary, ledger line items, fiscal years, contractors, covers)
 * Field-level origin: anything in source.json is "from source"; anything else is "extended".
 */
import type { AccountDef } from './contracts';

export type ClassId ='ALPHA' | 'BETA' | 'GAMMA' | 'DELTA';
export type FacilityId = `${ClassId}-${string}`; // ALPHA-01 .. DELTA-12
export type TierNo = 1 | 2 | 3 | 4;
export type MarkingId = 'TSSCI-OSC' | 'UMBRA-R' | 'UMBRA-C' | 'UMBRA-U' | 'UMBRA-EO';
export type Bearing = 'N' | 'NE' | 'E' | 'SE' | 'S' | 'SW' | 'W' | 'NW';
export type NetworkId = 'EASTERN' | 'SOUTHERN' | 'MOUNTAIN_WESTERN' | 'CENTRAL';
/** A redaction sentinel in the client canon, `[[RX:<key>:<len>]]` (see src/core/rx.ts). */
export type RxString = `[[RX:${string}]]`;
export type CompartmentId ='KESTREL' | 'HOLLOW' | 'SEXTANT' | 'TALLOW' | 'BRIAR' | 'QUARRY' | 'LANTERN';

export interface Marking {
  id: MarkingId;
  label: string; // exact banner text, e.g. "UMBRA//OSC EYES ONLY"
  sourceLabel: string; // as written in the lore
  rank: number; // 0 lowest .. 4 highest; banner shows the highest open
  bannerBg: string; // hex, fictional marking colour (banners/stamps only)
  bannerFg: string;
  usage: string; // what it is applied to
}

export interface Anchor {
  /** "N miles DIRECTION of CITY" form (ALPHA, BETA, some DELTA). */
  /** null only in the client canon (redacted; see src/core/rx.ts). */
  miles?: number | null;
  bearing?: Bearing | null;
  city: string; // "Lexington" (a redaction sentinel in the client canon for DELTA)
  state: string; // "KY"
  /** Public coordinates of the named city centre. null only in the client canon (redacted). */
  cityLat: number | null;
  cityLon: number | null;
  /** For GAMMA "area" descriptions, the area label as written. */
  areaLabel?: string;
}

export interface StaffLine {
  role: string;
  count: number;
}

export interface Facility {
  id: FacilityId;
  class: ClassId;
  codename: string | null; // "RAVEN MOUNTAIN"
  locationText: string; // as written (or extended)
  anchor: Anchor;
  /** Computed by canon-merge from anchor (great-circle destination). Never hand-typed.
   *  null only in the client canon, where the position is redacted (DELTA). */
  lat?: number | null;
  lon?: number | null;
  terrain: string | null; // "Blue Ridge Mountains. Hidden beneath defunct quarry site."
  coverIdentity: string | null;
  coverStory: string | null; // extended: 2-4 sentence public-facing cover story
  depthFt: number | null;
  completed: string | null; // "2003-11"
  capacity: number | null; // null only in the client canon (DELTA, T1) // surge berthing (see glossary SURGE BERTHING)
  sustainedMonths: number | null; // ALPHA only, from source
  staff: number | null; // null only in the client canon (DELTA, T1) // current posted staff
  staffBreakdown: StaffLine[]; // ALPHA from source; others extended (must sum to staff)
  function: string;
  connectionsText: string | null; // source rail-connection text, verbatim facts
  network: NetworkId | null;
  reactor: boolean | null; // null only in the client canon (withheld BETA, DELTA)
  commanderId: string | null; // roster personnel number
  levels?: FacilityLevel[]; // ALPHA only (extended): for the depth cross-section
  origin: 'source' | 'extended' | 'mixed';
}

export interface FacilityLevel {
  n: number; // 0 = surface cover facility
  name: string; // "Level 4: Records Stacks B"
  topFt: number; // depth to top of level (0 = surface)
  heightFt: number;
  tier: TierNo; // minimum tier to see this level's name (others redacted)
  notes: string;
}

export interface FacilityClass {
  id: ClassId;
  name: string; // "Command & Control Hubs"
  depthText: string; // "800 to 2,400 ft"
  depthMinFt: number | null;
  depthMaxFt: number | null;
  sustainabilityText: string;
  sustainDaysMin: number | null;
  sustainDaysMax: number | null;
  transitEntitlement: string;
  bullets: string[];
  count: number;
  statedCapacity: number; // aggregate as stated in source (DELTA 980)
  statedStaff: number;
}

export interface RailSegment {
  no: string; // "01".."06"
  a: FacilityId;
  b: FacilityId;
  routeNote: string;
  miles: number;
  hours: number;
  completed: string; // "2004-12"
  status: 'IN REVENUE SERVICE' | 'NOT IN REVENUE SERVICE';
}

export interface TramLink {
  from: FacilityId;
  to: FacilityId;
  label: string; // "(Maine)"
  miles: number;
  hours: number;
  kind: 'BETA' | 'GAMMA';
}

export interface TramNetwork {
  id: NetworkId;
  name: string;
  hubs: FacilityId[];
  links: TramLink[];
  statedTotalMi: number;
}

export interface Tier {
  tier: TierNo;
  name: string;
  count: number;
  composition: StaffLine[] | string[];
  clearance: string;
  clearanceMarking: MarkingId | null;
  knowledgeScope: string;
}

export interface Phase {
  n: 1 | 2 | 3 | 4 | 5;
  years: string; // "2001–2003"
  startYear: number;
  endYear: number;
  title: string;
  status: 'COMPLETE' | 'ACTIVE' | 'PROJECTED';
  recruited: number | null;
  cumulative: number | null;
  targetPct: number | null;
  targetCount: number | null;
  items: string[];
}

export interface BudgetCategory {
  id: string;
  name: string;
  amountB: number;
  pct: number;
}
export interface FundingSource {
  id: string;
  name: string;
  pct: number;
  amountB: number; // derived: pct * total, rounded to 0.01
}
export interface LineItem {
  no: string; // "LI-001"..."LI-127"
  department: 'DOD' | 'DOE' | 'DHS' | 'FEMA';
  sourceId: string; // FundingSource id
  categoryId: string; // BudgetCategory id
  title: string; // plausible appropriations title (cover)
  account: string; // invented account code
  amountM: number; // millions, sums by category must equal category amount
  fy: Record<string, number>; // "FY2001".."FY2008" -> millions
}

export interface Contractor {
  id: string; // "PC-01".."PC-47"
  name: string; // invented company name, never a real firm
  trade: string;
  subcontractors: number; // mean across 47 must be 8.3
  /** max 3. In the client canon, sites other than the operator's are sentinels (src/core/rx.ts). */
  sites: (FacilityId | RxString)[];
  compartmentNote: string;
}

export interface Reactor {
  id: string; // "RX-A01"
  site: FacilityId | RxString; // sentinel only in the client canon (withheld BETA site)
  designation: string;
  type: string;
  thermalMWt: number;
  electricMWe: number;
  commissioned: string;
  status: 'NOMINAL' | 'DEGRADED' | 'FAULT' | 'OFFLINE';
  statusNote: string;
}

export interface Division {
  id: string; // "RD" etc
  name: string; // "Records Division"
  site: FacilityId | null;
  mandate: string;
  headId: string | null;
}

/** An office inside a division (not counted as a division). Extender A. */
export interface Office {
  id: string; // "OGC"
  name: string; // "Office of General Counsel"
  parentDivision: string; // Division.id
  site: FacilityId | null;
}

export interface Person {
  pn: string; // personnel number, canon format
  name: string; // invented
  rank: string | null;
  role: string;
  tier: TierNo;
  site: FacilityId | 'DETACHED / UNPOSTED' | RxString; // sentinel only in the client canon (tier 1)
  divisionId: string | null;
  email: string; // in-world .mer address
  notes: string;
}

export interface Compartment {
  id: CompartmentId;
  name: string;
  scope: string; // what it unlocks, in-world
  briefingDocNo: string;
}

export interface CouncilSeat {
  seat: number; // 1..11
  category: string; // "Cabinet-level", "Agency director", ...
  holderLabel: string; // always redacted-able descriptor, never a real person
  since: string;
  notes: string;
}

export interface CharterArticle {
  n: number; // 1..7
  title: string;
  text: string; // Article I verbatim from source
}

export interface GlossaryTerm {
  term: string;
  def: string;
  seeAlso: string[];
}

export interface Anomaly {
  id: 'UNPOSTED_790' | 'TUNNEL_847' | 'CAPACITY_23400' | 'SEGMENT_04' | 'ELECTRONIC_COPY' | string;
  title: string;
  figures: Record<string, number | string>;
  canonAnswer: string;
  origin: 'brief' | 'extractor';
}

// ---- Additions for extended-b (threat detail, cover catalogue, real events, calendar, budget notes) ----

export interface ThreatProtocol {
  designation: string; // "OSC-CP-01"
  title: string | null; // null when withheld
  titleWithheld: boolean;
  pageCount: number; // the page count is never withheld
  revision: number;
  withholdingAuthority: string;
  ref: string;
}

export interface ThreatDetail {
  id: string; // matches threats.external[].id / threats.internal[].id
  group: 'external' | 'internal';
  label: string;
  ownerDivision: string; // division name as written by extender B
  ownerDivisionId: string | null; // computed by canon-merge from divisions (null when no match)
  contingency: string[];
  protocol: ThreatProtocol;
}

export interface CoverCatalogueEntry {
  facility: FacilityId;
  coverAgency: string;
  coverFacilityType: string;
  visibleSurfaceStaff: number | null; // null only in the client canon (SEXTANT rows)
  publicRecordsPosture: string;
  lastCoverReview: string; // ISO date <= 2008-05-31
}

export interface RealEvent {
  id: string; // "RE-01"
  date: string; // ISO
  dateText: string; // "17 FEB 2001"
  publicEvent: string;
  oscExplanation: string;
  citedIn: string;
}

export interface CalendarEvent {
  id: string; // "CAL-0805-01"
  date: string; // ISO, May 2008
  dateText: string;
  startZ: string | null; // "0900Z"
  endZ: string | null;
  timeText: string;
  facility: FacilityId;
  title: string;
  category: string;
  originator: string; // "CODE/SITE"
  tier: TierNo;
  note: string;
}

/** Extender A: paper trail behind each anomaly (keyed by Anomaly.id). */
export interface AnomalyNote {
  noticedBy: string; // personnel number
  closedBy?: string;
  actionOfficer?: string;
  documents: string[]; // docNos
  compartment: CompartmentId | null;
  notes: string;
}

// ---- Pass two: extended-c (accounts and shared plant data; docs/canon/extended-c.md) ----

/** Hardening class of planning model PM-3. */
export type HardeningClassId = 'H1' | 'H2' | 'H3' | 'H4';
export type SurvivabilityCondition = 'OPERATIONAL' | 'DEGRADED' | 'ISOLATED' | 'NOT ASSURED';

/** Strike-effects planning model (strike app). A plainly simplified, notional model. */
export interface Survivability {
  model: {
    id: string; // "PM-3"
    title: string;
    revision: number;
    date: string; // ISO
    originator: string; // "OCP/ALPHA-01"
    marking: MarkingId;
    disclaimer: string;
    method: string[]; // the model's rules in words (apps implement exactly these)
  };
  classes: { id: HardeningClassId; name: string; description: string; ratedPsi: number; depthCoupling: number }[];
  /** Model depth for a GAMMA site when the depth of record is not held (client canon: depthFt null). */
  gammaPlanningDepthFt: number;
  /** Ordered; condition = first whose maxRatio >= site psi / effective rating (null = otherwise). */
  conditions: { id: SurvivabilityCondition; maxRatio: number | null; text: string }[];
  /** Range (mi) = rangeCoeffMi x yieldKt^(1/3). Ordered by psi ascending (range descending). */
  contours: { psi: number; rangeCoeffMi: number }[];
  yieldsKt: number[];
  /** Every non-DELTA facility. */
  facilities: { facility: FacilityId; hardeningClass: HardeningClassId }[];
  notModelled: { classId: 'DELTA'; text: string };
}

export type DrillClassId = 'ALPHA' | 'BETA' | 'GAMMA';

/** One site's place in the seal drill order (computed by canon-merge from rail/tram links). */
export interface SealDrillStep {
  facility: FacilityId;
  network: NetworkId | null;
  /** Site that relays the order (null for the origin). */
  via: FacilityId | null;
  relay: 'origin' | 'rail' | 'tram' | 'voice';
  /** Relay hops from the origin. */
  hop: number;
  /** Drill minutes from the order to this site receiving it. */
  offsetMin: number;
}

export interface SealDrill {
  /** Drill minutes per real minute (the drill runs compressed). */
  timeScale: number;
  origin: FacilityId;
  /** Minutes from receipt of the order: acknowledge, door cycle, report sealed (sealMin >= ackMin + doorCycleMin). */
  classes: { classId: DrillClassId; ackMin: number; doorCycleMin: number; sealMin: number }[];
  relay: { hubHopMin: number; tramHopMin: number; unlinkedMin: number };
  rules: string[];
  excluded: { classId: 'DELTA'; text: string };
  /** Every non-DELTA facility, in order of receipt (computed). */
  sequence: SealDrillStep[];
}

export interface PlantLevel {
  n: number;
  name: string;
}

export type DoorKind = 'portal' | 'blast' | 'airlock';
export interface DoorDef {
  id: string; // "A01-BD3", "G08-PD1"
  level: number; // ALPHA: facility level n; BETA/GAMMA: templateLevels n
  location: string;
  kind: DoorKind;
  normal: 'open' | 'closed';
  cycleSec: number;
  ratedPsi: number | null;
  sealsOnDrill: boolean;
  /** Minimum tier to see this door (the level's tier for ALPHA). */
  tier: TierNo;
}
export interface AirlockDef {
  id: string; // "A01-AL1"
  level: number;
  location: string;
  outer: string; // DoorDef id (kind airlock); interlocked with `inner`
  inner: string;
  cycleSec: number;
  deconSec: number | null;
  tier: TierNo;
}
export interface SiteDoors {
  facility: FacilityId;
  source: 'detailed' | 'template';
  doors: DoorDef[];
  airlocks: AirlockDef[];
}

export type CameraKind = 'corridor' | 'portal' | 'platform' | 'vault' | 'hoist' | 'plant' | 'assembly';
export interface CameraDef {
  id: string; // "A03-C14"
  level: number;
  location: string;
  kind: CameraKind;
  ptz: boolean;
  tier: TierNo;
}
export interface SiteCameras {
  facility: FacilityId;
  source: 'detailed' | 'template';
  cameras: CameraDef[];
}

export interface Hoist {
  id: string; // "A01-H1"
  facility: FacilityId; // ALPHA only
  name: string;
  kind: 'personnel' | 'vehicle' | 'freight' | 'egress';
  /** Levels served (facility level numbers), ascending; the first is the collar. */
  levels: number[];
  speedFpm: number;
  accelSec: number;
  cagePersons: number;
  payloadLb: number;
  /** Computed: landing depth = level topFt + heightFt (the level floor). */
  stops: { level: number; depthFt: number }[];
  /** Computed: deepest landing minus collar landing. */
  travelFt: number;
}

export interface MusterPoint {
  id: string; // "A02-MP1"
  level: number;
  location: string;
  capacity: number;
  /** Posted staff assigned to this point; per site these sum to the facility's staff. */
  assigned: number;
}
export interface SiteMuster {
  facility: FacilityId;
  source: 'detailed' | 'template';
  points: MusterPoint[];
}

/**
 * Per-app canon fragments: content/canon/apps/<appId>.json, validated by the optional
 * src/core/canon-apps/<appId>.ts `schema`. Each app narrows its own entry with its schema type.
 */
export type CanonApps = Record<string, unknown>;

export interface Canon {
  anomalyNotes: Record<string, AnomalyNote>;
  threatDetail: ThreatDetail[];
  coverCatalogue: CoverCatalogueEntry[];
  realEvents: RealEvent[];
  calendar: CalendarEvent[];
  budgetNotes: string[];
  meta: {
    environment: string; // "MERIDIAN Workstation Environment"
    release: string; // "4.1.7"
    agency: string; // "Office of Strategic Continuity"
    inWorldDate: string; // "2008-05-19": the session date (src/core/session.ts). The date ceiling is DATE_CEILING (canon-schema).
    sourceDocNo: string;
    sourceRevision: string; // "2008-Q2"
  };
  headline: {
    facilities: number;
    hubs: number;
    capacitySustained: number; // 23,400
    capacitySurge: number; // 34,700 (sum of class capacities)
    staffTotal: number; // 3,847 (tier totals)
    staffPosted: number; // 3,057 (sum of facility staff)
    staffUnposted: number; // 790
    utilizationPct: number; // 16.4
    programCostB: number; // 287
    tunnelCertifiedMi: number; // 847
    railEngineeringMi: number; // computed sum of rail segments
    tramEngineeringMi: number; // computed sum of stated network totals
    tramLinkSumMi: number; // computed sum of every listed tram link
  };
  markings: Marking[];
  classes: FacilityClass[];
  facilities: Facility[];
  transitTech: Record<string, string>;
  railSegments: RailSegment[];
  tramNetworks: TramNetwork[];
  tiers: Tier[];
  ratioModel: { basis: string; capacity: number; rows: { function: string; pct: number; count: number }[]; note: string };
  phases: Phase[];
  security: {
    construction: { label: string; text: string }[];
    personnel: { investigation: string; focusAreas: string[]; compartmentation: string; communications: string };
  };
  reserves: {
    basisNote: string;
    items: { id: string; category: 'FOOD' | 'WATER' | 'MEDICAL' | 'ENERGY' | 'ARMAMENTS'; label: string; value: number | null; unit: string; text: string; site: FacilityId | null; tier: TierNo }[];
  };
  budget: {
    totalB: number;
    categories: BudgetCategory[];
    sources: FundingSource[];
    lineItemCount: number;
    departments: string[];
    auditNote: string;
    fiscalYears: { fy: string; totalM: number }[]; // extended
    lineItems: LineItem[]; // extended, length === lineItemCount
  };
  contractors: { primeCount: number; avgSubs: number; maxSitesKnown: number; register: Contractor[] };
  expansion: { phase4: string[]; phase5: string[] };
  threats: { external: { id: string; label: string; response: string }[]; internal: { id: string; label: string; response: string }[] };
  classificationControl: { label: string; text: string }[];
  legalNotice: string; // paraphrase-free source text is NOT shipped verbatim (fiction guardrail); see DECISIONS
  charter: CharterArticle[];
  council: { composition: StaffLine[]; seats: CouncilSeat[] };
  reactors: Reactor[];
  divisions: Division[];
  offices: Office[];
  compartments: Compartment[];
  roster: Person[];
  glossary: GlossaryTerm[];
  docNumbering: { family: string; pattern: string; example: string; notes: string }[];
  personnelNumberFormat: { pattern: string; example: string; notes: string };
  anomalies: Anomaly[];
  operator: {
    // the visitor's issued identity (in-world, printed on the temporary access card)
    operatorId: string;
    passphrase: string;
    pn: string;
    displayName: string; // e.g. "ANALYST (PROBATIONARY) 3-1147"
    tier: TierNo;
    site: FacilityId;
    divisionId: string;
    compartments: CompartmentId[];
    probationStart: string; // "2008-04-14"
    supervisorPn: string;
    email: string;
  };
  /* ---- pass two (extended-c) ---- */
  /** The four issued credentials (client-safe: never a Tier 2 name). */
  accounts: AccountDef[];
  survivability: Survivability;
  sealDrill: SealDrill;
  /** Level names for BETA and GAMMA plant records (ALPHA uses facilities[].levels). */
  templateLevels: Record<'BETA' | 'GAMMA', PlantLevel[]>;
  /** Every non-DELTA facility. */
  doors: SiteDoors[];
  /** Every non-DELTA facility. */
  cameras: SiteCameras[];
  /** ALPHA shafts. */
  hoists: Hoist[];
  /** Every non-DELTA facility. */
  musterPoints: SiteMuster[];
  apps: CanonApps;
}
